FFStatus NewOrderCross::toString(falconfix::FastBuffer &out, bool includeMilliseconds) const noexcept {
	static constexpr std::string_view HDR = "8=FIX4.3\x01""9=000000\x01""35=s\x01";
	static constexpr std::size_t HDR_BL_POS = 11;
	static constexpr std::size_t HDR_CALC_OFFSET = 18;

	out.clear();
	if (!out.reserve_noexcept(compute_buffer_size())) [[unlikely]] {
		return FF_SYS_ERR(BAD_ALLOC);
	}

	char *p = out.data();
	std::memcpy(p, HDR.data(), HDR.size());
	p += HDR.size();
	if ((p = m_Header.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, field_id::BeginString);
	}

	if (hasCrossID()) { WRITE_TAG4(fix43::tag_const::CrossID); std::memcpy(p, m_CrossID.data(), m_CrossID.size()); p += m_CrossID.size(); *p++ = fix43::serialize::SOH; }
	if (hasCrossType()) { WRITE_TAG4(fix43::tag_const::CrossType); p += falconfix::itoa(m_CrossType, p); *p++ = fix43::serialize::SOH; }
	if (hasCrossPrioritization()) { WRITE_TAG4(fix43::tag_const::CrossPrioritization); p += falconfix::itoa(m_CrossPrioritization, p); *p++ = fix43::serialize::SOH; }
	if (!m_NoSidesGroup.empty()) {
		WRITE_TAG4(fix43::tag_const::NoSides);
		p += falconfix::itoa(static_cast<int64_t>(m_NoSidesGroup.size()), p);
		*p++ = fix43::serialize::SOH;
		for (const auto &entry : m_NoSidesGroup) {
			p = entry.encode(p, includeMilliseconds);
		}
	}
	if ((p = m_Instrument.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, 0);
	}
	if (hasSettlmntTyp()) { WRITE_TAG3(fix43::tag_const::SettlmntTyp); *p++ = m_SettlmntTyp; *p++ = fix43::serialize::SOH; }
	if (hasFutSettDate()) { WRITE_TAG3(fix43::tag_const::FutSettDate); p += fix43::datetime::format_UTCDateOnly(m_FutSettDate, p); *p++ = fix43::serialize::SOH; }
	if (hasHandlInst()) { WRITE_TAG3(fix43::tag_const::HandlInst); *p++ = m_HandlInst; *p++ = fix43::serialize::SOH; }
	if (hasExecInst()) { WRITE_TAG3(fix43::tag_const::ExecInst); std::memcpy(p, m_ExecInst.data(), m_ExecInst.size()); p += m_ExecInst.size(); *p++ = fix43::serialize::SOH; }
	if (hasMinQty()) { WRITE_TAG4(fix43::tag_const::MinQty); p += falconfix::dtoa(m_MinQty, p); *p++ = fix43::serialize::SOH; }
	if (hasMaxFloor()) { WRITE_TAG4(fix43::tag_const::MaxFloor); p += falconfix::dtoa(m_MaxFloor, p); *p++ = fix43::serialize::SOH; }
	if (hasExDestination()) { WRITE_TAG4(fix43::tag_const::ExDestination); std::memcpy(p, m_ExDestination.data(), m_ExDestination.size()); p += m_ExDestination.size(); *p++ = fix43::serialize::SOH; }
	if (!m_NoTradingSessionsGroup.empty()) {
		WRITE_TAG4(fix43::tag_const::NoTradingSessions);
		p += falconfix::itoa(static_cast<int64_t>(m_NoTradingSessionsGroup.size()), p);
		*p++ = fix43::serialize::SOH;
		for (const auto &entry : m_NoTradingSessionsGroup) {
			p = entry.encode(p, includeMilliseconds);
		}
	}
	if (hasProcessCode()) { WRITE_TAG3(fix43::tag_const::ProcessCode); *p++ = m_ProcessCode; *p++ = fix43::serialize::SOH; }
	if (hasPrevClosePx()) { WRITE_TAG4(fix43::tag_const::PrevClosePx); p += falconfix::dtoa(m_PrevClosePx, p); *p++ = fix43::serialize::SOH; }
	if (hasLocateReqd()) { WRITE_TAG4(fix43::tag_const::LocateReqd); *p++ = m_LocateReqd ? 'Y' : 'N'; *p++ = fix43::serialize::SOH; }
	if (hasTransactTime()) { WRITE_TAG3(fix43::tag_const::TransactTime); p += fix43::datetime::format_UTCTimestamp_compact(m_TransactTime, p, includeMilliseconds); *p++ = fix43::serialize::SOH; }
	if ((p = m_Stipulations.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, 0);
	}
	if (hasOrdType()) { WRITE_TAG3(fix43::tag_const::OrdType); *p++ = m_OrdType; *p++ = fix43::serialize::SOH; }
	if (hasPriceType()) { WRITE_TAG4(fix43::tag_const::PriceType); p += falconfix::itoa(m_PriceType, p); *p++ = fix43::serialize::SOH; }
	if (hasPrice()) { WRITE_TAG3(fix43::tag_const::Price); p += falconfix::dtoa(m_Price, p); *p++ = fix43::serialize::SOH; }
	if (hasStopPx()) { WRITE_TAG3(fix43::tag_const::StopPx); p += falconfix::dtoa(m_StopPx, p); *p++ = fix43::serialize::SOH; }
	if ((p = m_SpreadOrBenchmarkCurveData.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, 0);
	}
	if ((p = m_YieldData.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, 0);
	}
	if (hasCurrency()) { WRITE_TAG3(fix43::tag_const::Currency); std::memcpy(p, m_Currency.data(), m_Currency.size()); p += m_Currency.size(); *p++ = fix43::serialize::SOH; }
	if (hasComplianceID()) { WRITE_TAG4(fix43::tag_const::ComplianceID); std::memcpy(p, m_ComplianceID.data(), m_ComplianceID.size()); p += m_ComplianceID.size(); *p++ = fix43::serialize::SOH; }
	if (hasIOIid()) { WRITE_TAG3(fix43::tag_const::IOIid); std::memcpy(p, m_IOIid.data(), m_IOIid.size()); p += m_IOIid.size(); *p++ = fix43::serialize::SOH; }
	if (hasQuoteID()) { WRITE_TAG4(fix43::tag_const::QuoteID); std::memcpy(p, m_QuoteID.data(), m_QuoteID.size()); p += m_QuoteID.size(); *p++ = fix43::serialize::SOH; }
	if (hasTimeInForce()) { WRITE_TAG3(fix43::tag_const::TimeInForce); *p++ = m_TimeInForce; *p++ = fix43::serialize::SOH; }
	if (hasEffectiveTime()) { WRITE_TAG4(fix43::tag_const::EffectiveTime); p += fix43::datetime::format_UTCTimestamp_compact(m_EffectiveTime, p, includeMilliseconds); *p++ = fix43::serialize::SOH; }
	if (hasExpireDate()) { WRITE_TAG4(fix43::tag_const::ExpireDate); p += fix43::datetime::format_UTCDateOnly(m_ExpireDate, p); *p++ = fix43::serialize::SOH; }
	if (hasExpireTime()) { WRITE_TAG4(fix43::tag_const::ExpireTime); p += fix43::datetime::format_UTCTimestamp_compact(m_ExpireTime, p, includeMilliseconds); *p++ = fix43::serialize::SOH; }
	if (hasGTBookingInst()) { WRITE_TAG4(fix43::tag_const::GTBookingInst); p += falconfix::itoa(m_GTBookingInst, p); *p++ = fix43::serialize::SOH; }
	if (hasMaxShow()) { WRITE_TAG4(fix43::tag_const::MaxShow); p += falconfix::dtoa(m_MaxShow, p); *p++ = fix43::serialize::SOH; }
	if (hasPegDifference()) { WRITE_TAG4(fix43::tag_const::PegDifference); p += falconfix::dtoa(m_PegDifference, p); *p++ = fix43::serialize::SOH; }
	if (hasDiscretionInst()) { WRITE_TAG4(fix43::tag_const::DiscretionInst); *p++ = m_DiscretionInst; *p++ = fix43::serialize::SOH; }
	if (hasDiscretionOffset()) { WRITE_TAG4(fix43::tag_const::DiscretionOffset); p += falconfix::dtoa(m_DiscretionOffset, p); *p++ = fix43::serialize::SOH; }
	if (hasCancellationRights()) { WRITE_TAG4(fix43::tag_const::CancellationRights); *p++ = m_CancellationRights; *p++ = fix43::serialize::SOH; }
	if (hasMoneyLaunderingStatus()) { WRITE_TAG4(fix43::tag_const::MoneyLaunderingStatus); *p++ = m_MoneyLaunderingStatus; *p++ = fix43::serialize::SOH; }
	if (hasRegistID()) { WRITE_TAG4(fix43::tag_const::RegistID); std::memcpy(p, m_RegistID.data(), m_RegistID.size()); p += m_RegistID.size(); *p++ = fix43::serialize::SOH; }
	if (hasDesignation()) { WRITE_TAG4(fix43::tag_const::Designation); std::memcpy(p, m_Designation.data(), m_Designation.size()); p += m_Designation.size(); *p++ = fix43::serialize::SOH; }
	if (hasAccruedInterestRate()) { WRITE_TAG4(fix43::tag_const::AccruedInterestRate); p += falconfix::dtoa(m_AccruedInterestRate, p); *p++ = fix43::serialize::SOH; }
	if (hasAccruedInterestAmt()) { WRITE_TAG4(fix43::tag_const::AccruedInterestAmt); p += falconfix::dtoa(m_AccruedInterestAmt, p); *p++ = fix43::serialize::SOH; }
	if (hasNetMoney()) { WRITE_TAG4(fix43::tag_const::NetMoney); p += falconfix::dtoa(m_NetMoney, p); *p++ = fix43::serialize::SOH; }

	if ((p = m_Trailer.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, field_id::SignatureLength);
	}

	const std::size_t msg_len_no_checksum = static_cast<std::size_t>(p - out.data());
	const std::size_t body_len = msg_len_no_checksum - HDR_CALC_OFFSET;

	char *digits = out.data() + HDR_BL_POS;
	digits[0] = '0' + ((body_len / 100000) % 10);
	digits[1] = '0' + ((body_len / 10000 ) % 10);
	digits[2] = '0' + ((body_len / 1000  ) % 10);
	digits[3] = '0' + ((body_len / 100   ) % 10);
	digits[4] = '0' + ((body_len / 10    ) % 10);
	digits[5] = '0' +  (body_len           % 10);

	std::uint32_t cksum = 0;
	for (const char *it = out.data(); it != out.data() + msg_len_no_checksum; ++it) {
		cksum += static_cast<unsigned char>(*it);
	}
	cksum &= 0xFF;

	*p++ = '1'; *p++ = '0'; *p++ = '=';
	*p++ = char('0' + (cksum / 100));
	*p++ = char('0' + ((cksum / 10) % 10));
	*p++ = char('0' + (cksum % 10));
	*p++ = fix43::serialize::SOH;
	out.commit(static_cast<std::size_t>(p - out.data()));
	return FF_OK();
}

bool NewOrderCross::setField(int32_t tag, const char *begin, const char *end) noexcept {
	const std::size_t len = static_cast<std::size_t>(end - begin);

	switch (tag) {
	case field_id::CrossID: setCrossID({begin, len}); return true;
	case field_id::CrossType: setCrossType(falconfix::atoi(begin, end)); return true;
	case field_id::CrossPrioritization: setCrossPrioritization(falconfix::atoi(begin, end)); return true;
	case field_id::SettlmntTyp: setSettlmntTyp(fix43::parser::parse_char(begin, end)); return true;
	case field_id::FutSettDate: setFutSettDate(fix43::parser::parse_date32(begin, end)); return true;
	case field_id::HandlInst: setHandlInst(fix43::parser::parse_char(begin, end)); return true;
	case field_id::ExecInst: setExecInst({begin, len}); return true;
	case field_id::MinQty: setMinQty(fix43::parser::parse_double(begin, end)); return true;
	case field_id::MaxFloor: setMaxFloor(fix43::parser::parse_double(begin, end)); return true;
	case field_id::ExDestination: setExDestination({begin, len}); return true;
	case field_id::ProcessCode: setProcessCode(fix43::parser::parse_char(begin, end)); return true;
	case field_id::PrevClosePx: setPrevClosePx(fix43::parser::parse_double(begin, end)); return true;
	case field_id::LocateReqd: setLocateReqd(fix43::parser::parse_bool(begin, end)); return true;
	case field_id::TransactTime: setTransactTime(falconfix::atoi(begin, end)); return true;
	case field_id::OrdType: setOrdType(fix43::parser::parse_char(begin, end)); return true;
	case field_id::PriceType: setPriceType(falconfix::atoi(begin, end)); return true;
	case field_id::Price: setPrice(fix43::parser::parse_double(begin, end)); return true;
	case field_id::StopPx: setStopPx(fix43::parser::parse_double(begin, end)); return true;
	case field_id::Currency: setCurrency({begin, len}); return true;
	case field_id::ComplianceID: setComplianceID({begin, len}); return true;
	case field_id::IOIid: setIOIid({begin, len}); return true;
	case field_id::QuoteID: setQuoteID({begin, len}); return true;
	case field_id::TimeInForce: setTimeInForce(fix43::parser::parse_char(begin, end)); return true;
	case field_id::EffectiveTime: setEffectiveTime(falconfix::atoi(begin, end)); return true;
	case field_id::ExpireDate: setExpireDate(fix43::parser::parse_date32(begin, end)); return true;
	case field_id::ExpireTime: setExpireTime(falconfix::atoi(begin, end)); return true;
	case field_id::GTBookingInst: setGTBookingInst(falconfix::atoi(begin, end)); return true;
	case field_id::MaxShow: setMaxShow(fix43::parser::parse_double(begin, end)); return true;
	case field_id::PegDifference: setPegDifference(fix43::parser::parse_double(begin, end)); return true;
	case field_id::DiscretionInst: setDiscretionInst(fix43::parser::parse_char(begin, end)); return true;
	case field_id::DiscretionOffset: setDiscretionOffset(fix43::parser::parse_double(begin, end)); return true;
	case field_id::CancellationRights: setCancellationRights(fix43::parser::parse_char(begin, end)); return true;
	case field_id::MoneyLaunderingStatus: setMoneyLaunderingStatus(fix43::parser::parse_char(begin, end)); return true;
	case field_id::RegistID: setRegistID({begin, len}); return true;
	case field_id::Designation: setDesignation({begin, len}); return true;
	case field_id::AccruedInterestRate: setAccruedInterestRate(fix43::parser::parse_double(begin, end)); return true;
	case field_id::AccruedInterestAmt: setAccruedInterestAmt(fix43::parser::parse_double(begin, end)); return true;
	case field_id::NetMoney: setNetMoney(fix43::parser::parse_double(begin, end)); return true;
	default: return false;
	}
}

